if (points.empty()) return BoundingBox2();

// Compute convex hull using monotone chain algorithm
std::vector<cg3::Point2d> hull;
{
    std::vector<cg3::Point2d> pts = points;
    std::sort(pts.begin(), pts.end(), [](const cg3::Point2d& a, const cg3::Point2d& b) {
        return a.x() < b.x() || (a.x() == b.x() && a.y() < b.y());
    });

    auto cross = [](const cg3::Point2d& O, const cg3::Point2d& A, const cg3::Point2d& B) {
        return (A.x() - O.x()) * (B.y() - O.y()) - (A.y() - O.y()) * (B.x() - O.x());
    };

    for (size_t i = 0; i < pts.size(); ++i) {
        while (hull.size() >= 2 && cross(hull[hull.size()-2], hull.back(), pts[i]) <= 0)
            hull.pop_back();
        hull.push_back(pts[i]);
    }
    size_t lower_hull = hull.size();
    for (int i = pts.size() - 2; i >= 0; --i) {
        while (hull.size() > lower_hull && cross(hull[hull.size()-2], hull.back(), pts[i]) <= 0)
            hull.pop_back();
        hull.push_back(pts[i]);
    }
    hull.pop_back(); // Remove duplicate last point
}

if (hull.size() < 3) {
    // Degenerate case: all points collinear
    BoundingBox2 bb;
    bb.min() = hull[0];
    bb.max() = hull[0];
    for (const auto& p : hull) {
        bb.min() = bb.min().min(p);
        bb.max() = bb.max().max(p);
    }
    return bb;
}

// Rotating calipers algorithm
double min_area = std::numeric_limits<double>::max();
cg3::Point2d best_min, best_max;

for (size_t i = 0; i < hull.size(); ++i) {
    size_t j = (i + 1) % hull.size();
    cg3::Point2d edge = hull[j] - hull[i];
    double edge_len = std::sqrt(edge.x() * edge.x() + edge.y() * edge.y());
    if (edge_len < 1e-10) continue;

    // Normalized edge direction
    double ex = edge.x() / edge_len;
    double ey = edge.y() / edge_len;

    // Perpendicular direction
    double px = -ey;
    double py = ex;

    // Project all hull points onto these axes
    double min_e = std::numeric_limits<double>::max();
    double max_e = -std::numeric_limits<double>::max();
    double min_p = std::numeric_limits<double>::max();
    double max_p = -std::numeric_limits<double>::max();

    for (const auto& p : hull) {
        double e_proj = (p.x() - hull[i].x()) * ex + (p.y() - hull[i].y()) * ey;
        double p_proj = (p.x() - hull[i].x()) * px + (p.y() - hull[i].y()) * py;

        min_e = std::min(min_e, e_proj);
        max_e = std::max(max_e, e_proj);
        min_p = std::min(min_p, p_proj);
        max_p = std::max(max_p, p_proj);
    }

    double area = (max_e - min_e) * (max_p - min_p);
    if (area < min_area) {
        min_area = area;

        // Compute the four corners of the bounding box
        cg3::Point2d origin = hull[i];
        cg3::Point2d corner1 = origin + cg3::Point2d(ex * min_e + px * min_p, ey * min_e + py * min_p);
        cg3::Point2d corner2 = origin + cg3::Point2d(ex * max_e + px * min_p, ey * max_e + py * min_p);
        cg3::Point2d corner3 = origin + cg3::Point2d(ex * max_e + px * max_p, ey * max_e + py * max_p);
        cg3::Point2d corner4 = origin + cg3::Point2d(ex * min_e + px * max_p, ey * min_e + py * max_p);

        // Find min and max of the rotated box
        best_min = corner1;
        best_max = corner1;
        best_min = best_min.min(corner2);
        best_min = best_min.min(corner3);
        best_min = best_min.min(corner4);
        best_max = best_max.max(corner2);
        best_max = best_max.max(corner3);
        best_max = best_max.max(corner4);
    }
}

return BoundingBox2(best_min, best_max);

